import fs from'node:fs';import zlib from'node:zlib';import assert from'node:assert/strict';import{createBodyAdapter}from'./load-adapter.mjs';
const a=createBodyAdapter(),root=new URL('../source/kaopu-mhr-workbench/',import.meta.url),cases=JSON.parse(fs.readFileSync(new URL('tests/cases.json',root))),raw=zlib.gunzipSync(fs.readFileSync(new URL('tests/reference.bin.gz',root))),refs=new Float32Array(raw.buffer,raw.byteOffset,raw.length/4);let max=0,k=0;for(const c of cases.cases){const r=a.engine.evaluate(c);for(const v of cases.indices)for(let xyz=0;xyz<3;xyz++)max=Math.max(max,Math.abs(r.vertices[v*3+xyz]-refs[k++]));}assert.equal(cases.cases.length,342);assert.ok(max<.001);const report={caseCount:cases.cases.length,verticesPerCase:cases.indices.length,maxErrorCm:max,passed:true,notes:'Restored original reference fixtures; instrumentation leaves native inference unchanged.'};fs.writeFileSync(new URL('instrumented-native-parity.json',import.meta.url),JSON.stringify(report,null,2));console.log(report);
